class Solution {

    /**
     * @param Integer[] $arr
     * @param Integer $k
     * @return Integer[]
     */
    function kthSmallestPrimeFraction($arr, $k) {
        $n = count($arr);

        // Binary search on fraction values between 0 and 1
        $left = 0.0;
        $right = 1.0;

        while ($right - $left > 1e-9) {
            $mid = ($left + $right) / 2;
            // count how many fractions are <= mid
            // keep track of the max fraction <= mid
            $count = 0;
            $maxNumer = 0;
            $maxDenom = 1;

            $j = 1;
            for ($i=0; $i < $n - 1; $i++) {
                // Move j pointer so that arr[i]/arr[j] <= mid
                while ($j < $n && $arr[$i] > $mid * $arr[$j]) {
                    $j++;
                }
                if ($j == $n) break;

                $count += $n - $j;
                // Check the smallest fraction <= mid with this i
                // Want to find the max fraction <= mid => arr[i]/arr[j] but this j is minimal possible for this i
                if ($maxNumer * $arr[$j] < $arr[$i] * $maxDenom) {
                    $maxNumer = $arr[$i];
                    $maxDenom = $arr[$j];
                }
            }

            if ($count == $k) {
                return [$maxNumer, $maxDenom];
            } elseif ($count < $k) {
                $left = $mid;
            } else {
                $right = $mid;
            }
        }

        // When converged, left ~ right
        // return the stored max fraction <= left
        // To find the exact fraction on convergence (rarely the first maxNumer,maxDenom is set),
        // do one more pass similar to above at left.

        $count = 0;
        $maxNumer = 0;
        $maxDenom = 1;
        $j = 1;
        for ($i = 0; $i < $n - 1; $i++) {
            while ($j < $n && $arr[$i] > $left * $arr[$j]) {
                $j++;
            }
            if ($j == $n) break;
            $count += $n - $j;
            if ($maxNumer * $arr[$j] < $arr[$i] * $maxDenom) {
                $maxNumer = $arr[$i];
                $maxDenom = $arr[$j];
            }
        }
        return [$maxNumer, $maxDenom];
    }
}

